<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);
if(!class_exists('ZipArchive')){fwrite(STDERR,"Enable PHP ZIP.\n");exit(1);}
$root=dirname(__DIR__);if(!is_dir($root.'/dist'))mkdir($root.'/dist',0750,true);$output=$root.'/dist/annam-foods-hostinger.zip';$zip=new ZipArchive();if($zip->open($output,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Cannot create package.');$hashes=[];
foreach(['src','views','resources','bin','deploy','tests'] as $directory)foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/'.$directory,FilesystemIterator::SKIP_DOTS)) as $file){if(!$file->isFile()||$file->isLink())continue;$relative=substr($file->getPathname(),strlen($root)+1);if(!in_array(strtolower($file->getExtension()),['php','py','md','txt','css','js','png','jpg','jpeg','webp','svg','gif','avif','json','htaccess'],true))continue;$target='annam-private/'.$relative;$zip->addFile($file->getPathname(),$target);$hashes[$target]=hash_file('sha256',$file->getPathname());}
foreach(['README.md','ARCHITECTURE.md','.env.example','storage/sessions/.gitkeep','storage/logs/.gitkeep'] as $relative){$target='annam-private/'.$relative;$zip->addFile($root.'/'.$relative,$target);$hashes[$target]=hash_file('sha256',$root.'/'.$relative);}
foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/public/assets',FilesystemIterator::SKIP_DOTS)) as $file){if(!$file->isFile()||$file->isLink())continue;$relative=substr($file->getPathname(),strlen($root.'/public/'));$zip->addFile($file->getPathname(),'public_html/'.$relative);$hashes['public_html/'.$relative]=hash_file('sha256',$file->getPathname());}
$entry="<?php\ndeclare(strict_types=1);\nrequire dirname(__DIR__).'/annam-private/src/bootstrap.php';\n\\Annam\\Application::run();\n";$zip->addFromString('public_html/index.php',$entry);$hashes['public_html/index.php']=hash('sha256',$entry);
foreach(['public/.htaccess'=>'public_html/.htaccess','deploy/media.htaccess'=>'public_html/media/.htaccess'] as $source=>$target){$zip->addFile($root.'/'.$source,$target);$hashes[$target]=hash_file('sha256',$root.'/'.$source);}
$zip->addFromString('CHECKSUMS.json',json_encode($hashes,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$zip->addFromString('INSTALL-FIRST.txt',"Read annam-private/README.md before deployment.\nConfirm PHP pdo_pgsql, curl, mbstring, fileinfo, openssl and zip on Hostinger.\nRestore a database COPY for staging first. Keep the existing application available.\nCopy your saved media into public_html/media. Configure private .env with absolute MEDIA_ROOT.\nNo database, uploaded photos, passwords, environment file, live keys or sessions are in this ZIP.\nRun preflight, additive preparation, audit and provider acceptance before cutover.\n");$zip->close();echo "Hostinger package created without credentials, database, uploaded media or sessions.\n";
